/**
 * 监听元素进入视口；
 */
export declare function useIntersectionObserver(options?: IntersectionObserverInit): {
    /**
     * 监听实例
     */
    observer: IntersectionObserver;
    /**
     * 创建监听实例
     * el: 添加监听的元素
     * listener: 进入视口回调, 移除监听时需要指定该监听函数
     */
    observe: (el: HTMLElement, listener: (entry: IntersectionObserverEntry) => void) => IntersectionObserver | null;
    /**
     * 移除对某元素的监听
     * el: 要移除监听的元素
     * listener: 要移除的监听函数，如果不传，则使用初始化时的回调
     */
    unobserve: (el: HTMLElement, listener: (entry: IntersectionObserverEntry) => void) => void;
    /**
     * 销毁观察器
     */
    destroy(): void;
};
